    # Count the occurrences of each tile
    count = Counter(tiles)

    # Function to check if there is a koutsu
    def has_koutsu(count):
        return any(v >= 3 for v in count.values())

    # Function to check if there is a shuntsu
    def has_shuntsu(count):
        suits = {'m': '123456789', 'p': '123456789', 's': '123456789'}
        for suit in suits:
            tiles = ''.join([tile[1] for tile in tiles if tile[0] == suit])
            for i in range(len(tiles) - 2):
                if tiles[i:i+3] in suits[suit]:
                    return True
        return False

    # Check if there is already a mentsu
    if has_koutsu(count) or has_shuntsu(count):
        return 0

    # Calculate the minimum number of extra tiles needed
    extra_tiles = 0
    for tile in set(tiles):
        if count[tile] < 3:
            extra_tiles += 3 - count[tile]

    # Ensure we have enough tiles to form a shuntsu if needed
    if not has_shuntsu(count):
        extra_tiles -= 3 * len(set(tile[0] for tile in tiles))

    return max(extra_tiles, 0)

